      },
      {
        "name": "Error Handling",
        "passed": false,
        "reason": "Only basic try/finally in sendEvents and a generic processError handler. No RestError inspection, no retry logic, no timeout configuration. Main catch is generic."
      },
      {
        "name": "Code Quality",
        "passed": true,
        "reason": "Clean, well-structured code with clear separation of sendEvents and receiveEvents functions. Good comments, proper TypeScript typing, and graceful shutdown with signal handlers."
      },
      {
        "name": "Correct @azure/ Scoped Packages",
        "passed": true,
        "reason": "All Azure SDK dependencies use @azure/ scoped packages: @azure/event-hubs, @azure/eventhubs-checkpointstore-blob, @azure/storage-blob. No deprecated unscoped packages."
      },
      {
        "name": "@azure/identity for Authentication",
